const axios = require('axios');

async function getReelsData(url) {
  try {
    const response = await axios.get('https://igexport.com/api/ig-reels/', {
      params: {
        url: url
      }
    });
    return response.data;
  } catch (error) {
    console.error('Error fetching reels data:', error);
    throw error;
  }
}

